import { A11yModule } from '@angular/cdk/a11y';
import { CdkConnectedOverlay, CdkOverlayOrigin, ConnectedPosition } from '@angular/cdk/overlay';
import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  Injector,
  afterNextRender,
  computed,
  inject,
  input,
  output,
  signal,
  viewChild,
} from '@angular/core';
import { MatCalendar, MatCalendarCellClassFunction, DateFilterFn } from '@angular/material/datepicker';
import { format, isMonday, isWithinInterval, parseISO } from 'date-fns';
import { WeekRange } from '../../../core/models';
import { formatSelectableWeeks, formatWeekRange } from '../week';
import { Icon } from './icon';

const ISO_DATE_FORMAT = 'yyyy-MM-dd';
const SELECTED_WEEK_CLASS = 'week-picker-selected-week';

let nextDialogId = 0;

@Component({
  selector: 'app-week-picker',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [A11yModule, CdkConnectedOverlay, CdkOverlayOrigin, Icon, MatCalendar],
  template: `
    <button
      #trigger
      type="button"
      class="trigger"
      cdkOverlayOrigin
      #triggerOrigin="cdkOverlayOrigin"
      aria-haspopup="dialog"
      [attr.aria-expanded]="isOpen()"
      [attr.aria-controls]="isOpen() ? dialogId : null"
      [attr.aria-label]="triggerName()"
      [disabled]="isDisabled()"
      (click)="toggle()"
    >
      <span class="trigger-label">
        <app-icon class="calendar-icon" name="calendar" [size]="18" />
        <span aria-live="polite">{{ weekLabel() }}</span>
      </span>
      <app-icon class="chevron-icon" [name]="isOpen() ? 'chevron-up' : 'chevron-down'" />
    </button>

    <ng-template
      cdkConnectedOverlay
      [cdkConnectedOverlayOrigin]="triggerOrigin"
      [cdkConnectedOverlayOpen]="isOpen()"
      [cdkConnectedOverlayPositions]="popoverPositions"
      (attach)="focusSelectedWeek()"
      (detach)="close()"
      (overlayOutsideClick)="closeOnOutsideClick($event)"
    >
      <div class="week-picker-dialog" role="dialog" aria-label="Choose week" [id]="dialogId" cdkTrapFocus>
        <mat-calendar
          [startAt]="selectedMonday()"
          [selected]="selectedMonday()"
          [minDate]="earliestMonday()"
          [maxDate]="latestCompleteMonday()"
          [dateFilter]="isSelectableMonday"
          [dateClass]="selectedWeekClass"
          (_userSelection)="choose($event.value)"
        />
        <div class="helper">
          <p>Weeks run Monday to Sunday.</p>
          <p>{{ selectableWeeksLabel() }}</p>
        </div>
      </div>
    </ng-template>
  `,
  styles: `
    :host { display: block; position: relative; }
    .trigger {
      width: var(--week-picker-trigger-width); height: 44px; padding: 0 14px; display: flex; align-items: center; justify-content: space-between; gap: 10px;
      border: 1px solid var(--color-control-border); background: var(--color-surface); color: var(--color-ink); cursor: pointer; font: inherit;
    }
    .trigger[aria-expanded='true'] { border-color: var(--color-ink); box-shadow: inset 0 0 0 1px var(--color-ink); }
    .trigger:disabled { background: var(--color-disabled-fill); border-color: var(--color-disabled-border); color: var(--color-ink-2); cursor: not-allowed; }
    .trigger-label { display: flex; align-items: center; gap: 10px; font-size: 15px; font-weight: 600; font-variant-numeric: tabular-nums; white-space: nowrap; }
    .chevron-icon { color: var(--color-ink-2); }
    .trigger[aria-expanded='true'] .chevron-icon { color: var(--color-ink); }
    .trigger:disabled .calendar-icon { color: var(--color-disabled-ink); }
    .trigger:disabled .chevron-icon { color: var(--color-disabled-chevron); }
  `,
})
export class WeekPicker {
  readonly week = input.required<WeekRange>();
  readonly earliestWeek = input.required<string>();
  readonly latestCompleteWeek = input.required<string>();

  readonly weekSelected = output<string>();

  private readonly injector = inject(Injector);
  private readonly trigger = viewChild.required<ElementRef<HTMLButtonElement>>('trigger');
  private readonly calendar = viewChild(MatCalendar);

  protected readonly dialogId = `week-picker-dialog-${nextDialogId++}`;
  protected readonly popoverPositions: ConnectedPosition[] = [
    { originX: 'start', originY: 'bottom', overlayX: 'start', overlayY: 'top', offsetY: 8 },
    { originX: 'start', originY: 'top', overlayX: 'start', overlayY: 'bottom', offsetY: -8 },
  ];

  protected readonly isOpen = signal(false);
  protected readonly isDisabled = computed(() => this.earliestWeek() === this.latestCompleteWeek());
  protected readonly weekLabel = computed(() => formatWeekRange(this.week().start, this.week().end));
  protected readonly triggerName = computed(() => `${this.weekLabel()}, choose week`);
  protected readonly selectableWeeksLabel = computed(() => formatSelectableWeeks(this.earliestWeek(), this.latestCompleteWeek()));
  protected readonly selectedMonday = computed(() => parseISO(this.week().start));
  protected readonly selectedSunday = computed(() => parseISO(this.week().end));
  protected readonly earliestMonday = computed(() => parseISO(this.earliestWeek()));
  protected readonly latestCompleteMonday = computed(() => parseISO(this.latestCompleteWeek()));

  protected readonly isSelectableMonday: DateFilterFn<Date> = (day) =>
    day !== null && isMonday(day) && isWithinInterval(day, { start: this.earliestMonday(), end: this.latestCompleteMonday() });

  protected readonly selectedWeekClass: MatCalendarCellClassFunction<Date> = (day, view) =>
    view === 'month' && !isMonday(day) && isWithinInterval(day, { start: this.selectedMonday(), end: this.selectedSunday() })
      ? SELECTED_WEEK_CLASS
      : '';

  protected toggle(): void {
    if (this.isOpen()) {
      this.close();
    } else {
      this.isOpen.set(true);
    }
  }

  protected close(): void {
    if (!this.isOpen()) {
      return;
    }
    this.isOpen.set(false);
    this.trigger().nativeElement.focus();
  }

  protected closeOnOutsideClick(event: MouseEvent): void {
    if (!(event.target instanceof Node && this.trigger().nativeElement.contains(event.target))) {
      this.close();
    }
  }

  protected focusSelectedWeek(): void {
    afterNextRender(() => this.calendar()?.focusActiveCell(), { injector: this.injector });
  }

  protected choose(day: Date | null): void {
    if (day === null) {
      return;
    }
    const chosenWeek = format(day, ISO_DATE_FORMAT);
    this.close();
    if (chosenWeek !== this.week().start) {
      this.weekSelected.emit(chosenWeek);
    }
  }
}
import { ChangeDetectionStrategy, Component, computed, input, output } from '@angular/core';
import { Account, EVENT_TYPES, EventType, WeekRange } from '../../../core/models';
import { isEventType } from '../event-type-guard';
import { EVENT_TYPE_LABELS } from '../health-copy';
import { addWeeks } from '../week';
import { Icon } from './icon';
import { WeekPicker } from './week-picker';

@Component({
  selector: 'app-dashboard-filters',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [Icon, WeekPicker],
  template: `
    <div class="field account-field">
      <label class="field-label" for="viewing-as">Viewing as</label>
      <div class="select-control">
        <select id="viewing-as" (change)="onAccountChange($event)">
          @for (account of accounts(); track account.id) {
            <option [value]="account.id" [selected]="account.id === accountId()">{{ account.name }}</option>
          }
        </select>
        <app-icon class="select-chevron" name="chevron-down" [size]="18" />
      </div>
    </div>

    @if (weekStepper(); as stepper) {
      <div class="field week-field" role="group" aria-labelledby="week-control-label">
        <span class="field-label" id="week-control-label">Week</span>
        <div class="week-control">
          <button type="button" class="step previous" [disabled]="!stepper.canGoToPreviousWeek" (click)="stepWeek(stepper.week.start, -1)">
            ◀ Previous week
          </button>
          <app-week-picker
            [week]="stepper.week"
            [earliestWeek]="stepper.earliestWeek"
            [latestCompleteWeek]="stepper.latestCompleteWeek"
            (weekSelected)="weekSelected.emit($event)"
          />
          <button type="button" class="step next" [disabled]="!stepper.canGoToNextWeek" (click)="stepWeek(stepper.week.start, 1)">Next week ▶</button>
        </div>
      </div>
    } @else {
      <div class="field week-field" aria-hidden="true">
        <span class="field-label">Week</span>
        <div class="week-placeholder"><span></span><span></span><span></span></div>
      </div>
    }

    <div class="field type-field">
      <label class="field-label" for="activity-type">Activity type</label>
      <div class="select-control">
        <select id="activity-type" (change)="onEventTypeChange($event)">
          @for (option of eventTypeOptions; track option.value) {
            <option [value]="option.value" [selected]="option.value === eventType()">{{ option.label }}</option>
          }
        </select>
        <app-icon class="select-chevron" name="chevron-down" [size]="18" />
      </div>
    </div>
  `,
  styles: `
    :host { display: flex; gap: 24px; align-items: flex-end; }
    .field { display: flex; flex-direction: column; gap: 6px; }
    .field-label { font-size: 13px; line-height: 18px; font-weight: 500; color: var(--color-ink-2); }
    .account-field { width: var(--account-field-width); }
    .week-field { width: var(--week-field-width); }
    .type-field { width: var(--type-field-width); }
    .select-control { position: relative; }
    select {
      appearance: none; width: 100%; height: 44px; padding: 0 40px 0 14px; font: inherit; font-size: 15px; color: var(--color-ink);
      border: 1px solid var(--color-control-border); border-radius: 8px; background: var(--color-surface); cursor: pointer;
    }
    .select-chevron { position: absolute; right: 14px; top: 13px; pointer-events: none; color: var(--color-ink-2); }
    .week-control { display: flex; height: 44px; }
    .week-control > * { margin-left: -1px; }
    .week-control > :first-child { margin-left: 0; }
    .week-control > :focus-visible, app-week-picker:focus-within { z-index: 1; }
    .step {
      box-sizing: border-box; flex: none; height: 44px; padding: 0 16px; font: inherit; font-size: 14px; font-weight: 500; color: var(--color-ink); white-space: nowrap;
      border: 1px solid var(--color-control-border); background: var(--color-surface); cursor: pointer;
    }
    .previous { width: var(--week-step-previous-width); border-radius: 8px 0 0 8px; }
    .next { width: var(--week-step-next-width); border-radius: 0 8px 8px 0; }
    .step:disabled { background: var(--color-disabled-fill); border-color: var(--color-disabled-border); color: var(--color-disabled-ink); cursor: not-allowed; }
    .week-placeholder {
      box-sizing: border-box; height: 44px; display: flex; align-items: center; gap: 12px; padding: 0 16px;
      border: 1px dashed var(--color-disabled-border); border-radius: 8px; background: var(--color-disabled-fill);
    }
    .week-placeholder span { width: 110px; height: 12px; border-radius: 6px; background: var(--color-line); }
    .week-placeholder span:nth-child(2) { width: 220px; margin-left: 40px; }
    .week-placeholder span:nth-child(3) { width: 90px; margin-left: auto; }
  `,
})
export class DashboardFilters {
  readonly accounts = input.required<readonly Account[]>();
  readonly accountId = input.required<number>();
  readonly week = input<WeekRange | null>(null);
  readonly earliestWeek = input<string | null>(null);
  readonly latestCompleteWeek = input<string | null>(null);
  readonly eventType = input.required<EventType>();

  readonly accountSelected = output<number>();
  readonly weekSelected = output<string>();
  readonly eventTypeSelected = output<EventType>();

  protected readonly eventTypeOptions = EVENT_TYPES.map((value) => ({ value, label: EVENT_TYPE_LABELS[value] }));
  protected readonly weekStepper = computed(() => {
    const week = this.week();
    const earliestWeek = this.earliestWeek();
    const latestCompleteWeek = this.latestCompleteWeek();
    if (week === null || earliestWeek === null || latestCompleteWeek === null) {
      return null;
    }
    return {
      week,
      earliestWeek,
      latestCompleteWeek,
      canGoToPreviousWeek: week.start > earliestWeek,
      canGoToNextWeek: week.start < latestCompleteWeek,
    };
  });

  protected onAccountChange(event: Event): void {
    this.accountSelected.emit(Number((event.target as HTMLSelectElement).value));
  }

  protected onEventTypeChange(event: Event): void {
    const selectedValue = (event.target as HTMLSelectElement).value;
    if (isEventType(selectedValue)) {
      this.eventTypeSelected.emit(selectedValue);
    }
  }

  protected stepWeek(weekStart: string, weekCount: number): void {
    this.weekSelected.emit(addWeeks(weekStart, weekCount));
  }
}

